package com.benabdallah.csvpipeline.api;
import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.PlatformTransactionManager; import org.springframework.transaction.support.TransactionTemplate;
@Component public class OutboxPublisher { private final JdbcClient jdbc;private final KafkaTemplate<String,String> kafka;private final String topic;private final String owner=UUID.randomUUID().toString();private final TransactionTemplate transaction;public OutboxPublisher(JdbcClient jdbc,KafkaTemplate<String,String> kafka,PlatformTransactionManager manager,@Value("${pipeline.kafka.topic:csv-upload-ready.v1}")String topic){this.jdbc=jdbc;this.kafka=kafka;this.topic=topic;this.transaction=new TransactionTemplate(manager);}
 @Scheduled(fixedDelayString="${pipeline.outbox.delay-ms:1000}") public void publish(){for(var e:claim()){try{kafka.send(topic,e.aggregate.toString(),e.payload).get();jdbc.sql("UPDATE outbox_event SET published_at=now(),lease_owner=NULL,lease_until=NULL WHERE id=:id AND lease_owner=:owner").param("id",e.id).param("owner",owner).update();}catch(Exception failure){jdbc.sql("UPDATE outbox_event SET available_at=now()+interval '5 seconds',lease_owner=NULL,lease_until=NULL,last_error=:error WHERE id=:id AND lease_owner=:owner").param("error",failure.getClass().getSimpleName()).param("id",e.id).param("owner",owner).update();}}}
 private List<Event> claim(){return transaction.execute(status->jdbc.sql("WITH candidates AS (SELECT id FROM outbox_event WHERE published_at IS NULL AND available_at<=now() AND (lease_until IS NULL OR lease_until<now()) ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 20) UPDATE outbox_event o SET lease_owner=:owner,lease_until=now()+interval '30 seconds',attempts=attempts+1 FROM candidates c WHERE o.id=c.id RETURNING o.id,o.aggregate_id,o.payload::text").param("owner",owner).query((r,n)->new Event(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3))).list());} private record Event(UUID id,UUID aggregate,String payload){}
}
